module.exports = [
{ e: "🗺️", art: { b: "🗺️", s: ["🧭", "📏", "⛰️", "🏞️"], c: ["#3A2A0B", "#8A6A2C"] },
pt: { h: "Leo abriu um mapa antigo e viu uma linha reta riscada no meio da América do Sul. “Quem desenhou isso?”, perguntou. O vovô explicou que, antes mesmo de chegarem aqui, Portugal e Espanha já tinham combinado como dividir as terras. “Mas o Brasil acabou ficando bem maior que essa linha”, disse.", t: "O Brasil cresce para o oeste", f: "Em 1494, Portugal e Espanha assinaram o Tratado de Tordesilhas, uma linha imaginária que dividia as terras entre os dois reinos. Com o tempo, expedições foram cada vez mais para o interior, e o Brasil passou muito dessa linha.", x: "Hoje o Brasil tem mais de 8,5 milhões de quilômetros quadrados e é o quinto maior país do mundo!", s: ["Os povos indígenas que viviam no continente não foram consultados sobre essa divisão.", "Os bandeirantes eram grupos que saíam de São Paulo para o interior em busca de ouro e pedras preciosas, e muitas vezes também capturavam indígenas.", "Os rios foram as principais estradas para explorar o interior."], ex: { t: "Dividindo o mapa", m: "um mapa da América do Sul impresso ou desenhado, uma régua, um barbante", p: ["Estique o barbante de cima a baixo no mapa, passando mais ou menos por Belém e por Santa Catarina.", "Pinte de um lado o que seria de Portugal e do outro o que seria da Espanha.", "Agora compare com o mapa do Brasil de hoje: quanto o país cresceu além da linha?"] }, at: "Diário de expedição", m: "papel, lápis de cor", p: ["Imagine uma viagem de canoa por um rio do Brasil.", "Desenhe três coisas que você veria: animais, plantas e paisagens.", "Escreva um pequeno diário da viagem e cole no álbum."], q: "Se você pudesse explorar um lugar do Brasil, para onde iria?" },
en: { h: "Leo opened an old map and saw a straight line drawn down the middle of South America. “Who drew this?” he asked. Grandpa explained that even before arriving here, Portugal and Spain had already agreed on how to split the land. “But Brazil ended up much bigger than that line,” he said.", t: "Brazil grows westward", f: "In 1494, Portugal and Spain signed the Treaty of Tordesillas, an imaginary line dividing lands between the two kingdoms. Over time, expeditions went farther and farther inland, and Brazil grew well past that line.", x: "Today Brazil covers more than 8.5 million square kilometers (3.2 million square miles) and is the fifth-largest country in the world!", s: ["The Indigenous peoples living on the continent were never asked about this division.", "The bandeirantes were groups that left São Paulo for the interior looking for gold and gems, and they often captured Indigenous people as well.", "Rivers were the main roads for exploring the interior."], ex: { t: "Splitting the map", m: "a printed or hand-drawn map of South America, a ruler, a piece of string", p: ["Stretch the string from top to bottom on the map, passing roughly through Belém and Santa Catarina.", "Color one side as Portugal's and the other as Spain's.", "Now compare with today's map of Brazil: how much did the country grow beyond the line?"] }, at: "Expedition diary", m: "paper, colored pencils", p: ["Imagine a canoe trip along a river in Brazil.", "Draw three things you'd see: animals, plants and landscapes.", "Write a short trip diary and glue it into the album."], q: "If you could explore any place in Brazil, where would you go?" },
es: { h: "Leo abrió un mapa antiguo y vio una línea recta trazada en medio de América del Sur. “¿Quién dibujó esto?”, preguntó. El abuelo explicó que, antes incluso de llegar aquí, Portugal y España ya habían acordado cómo dividir las tierras. “Pero Brasil terminó siendo mucho más grande que esa línea”, dijo.", t: "Brasil crece hacia el oeste", f: "En 1494, Portugal y España firmaron el Tratado de Tordesillas, una línea imaginaria que dividía las tierras entre los dos reinos. Con el tiempo, las expediciones fueron cada vez más hacia el interior, y Brasil pasó mucho más allá de esa línea.", x: "¡Hoy Brasil tiene más de 8,5 millones de kilómetros cuadrados y es el quinto país más grande del mundo!", s: ["A los pueblos indígenas que vivían en el continente nunca se les preguntó sobre esa división.", "Los bandeirantes eran grupos que salían de São Paulo hacia el interior en busca de oro y piedras preciosas, y muchas veces también capturaban indígenas.", "Los ríos fueron los principales caminos para explorar el interior."], ex: { t: "Dividiendo el mapa", m: "un mapa de América del Sur impreso o dibujado, una regla, un cordel", p: ["Estira el cordel de arriba abajo en el mapa, pasando más o menos por Belém y por Santa Catarina.", "Pinta de un lado lo que sería de Portugal y del otro lo que sería de España.", "Ahora compáralo con el mapa de Brasil de hoy: ¿cuánto creció el país más allá de la línea?"] }, at: "Diario de expedición", m: "papel, lápices de colores", p: ["Imagina un viaje en canoa por un río de Brasil.", "Dibuja tres cosas que verías: animales, plantas y paisajes.", "Escribe un pequeño diario del viaje y pégalo en el álbum."], q: "Si pudieras explorar un lugar de Brasil, ¿adónde irías?" } },

{ e: "🪙", art: { b: "⛏️", s: ["🪙", "💎", "⛪", "🏔️"], c: ["#4E3A0B", "#D4A82C"] },
pt: { h: "Nina achou uma pedrinha brilhante no caminho e gritou: “Ouro!”. Era só uma pedrinha com brilho de mica, mas o vovô aproveitou a deixa. “Há uns trezentos anos, muita gente correu para Minas Gerais por causa de pedrinhas assim”, contou. “Só que lá eram de ouro de verdade.”", t: "A corrida do ouro em Minas", f: "No fim dos anos 1600, foi descoberto muito ouro em Minas Gerais. Milhares de pessoas foram para lá, e surgiram cidades como Vila Rica, que hoje se chama Ouro Preto. Boa parte do ouro foi levada para Portugal.", x: "Ouro Preto foi o primeiro lugar do Brasil a ser declarado Patrimônio Mundial pela UNESCO, em 1980!", s: ["As igrejas de Minas têm muitas decorações douradas, num estilo chamado barroco.", "O artista mais famoso dessa época foi o Aleijadinho, que esculpia em pedra-sabão e madeira.", "Mesmo com uma doença que afetou suas mãos, o Aleijadinho continuou criando obras incríveis."], ex: { t: "Garimpo na bacia", m: "uma bacia com água, um prato fundo, areia, algumas porcas ou arruelas de metal (o “ouro”)", p: ["Misture a areia com as porquinhas de metal no prato fundo.", "Coloque um pouco de água e balance o prato em círculos, inclinado sobre a bacia.", "A areia leve vai saindo e o metal pesado fica no fundo: é assim que os garimpeiros separavam o ouro!"] }, at: "Arte barroca", m: "papel, lápis dourado ou amarelo, lápis de cor", p: ["Desenhe a fachada de uma igreja com duas torres.", "Enfeite com muitas curvas, espirais e flores, bem caprichado como no barroco.", "Pinte detalhes de dourado e cole no álbum."], q: "Se você achasse um tesouro, o que faria com ele?" },
en: { h: "Nina found a shiny pebble on the path and shouted, “Gold!” It was just a pebble sparkling with mica, but Grandpa took the hint. “About three hundred years ago, lots of people rushed to Minas Gerais because of pebbles like this,” he said. “Only there, they were real gold.”", t: "The gold rush in Minas", f: "In the late 1600s, a lot of gold was discovered in Minas Gerais. Thousands of people moved there, and towns like Vila Rica, now called Ouro Preto, sprang up. Much of the gold was shipped to Portugal.", x: "Ouro Preto was the first place in Brazil to be named a UNESCO World Heritage Site, in 1980!", s: ["The churches of Minas have lots of golden decoration, in a style called Baroque.", "The most famous artist of that time was Aleijadinho, who carved soapstone and wood.", "Even with an illness that affected his hands, Aleijadinho kept creating incredible works."], ex: { t: "Panning in a basin", m: "a basin of water, a deep plate, sand, a few metal nuts or washers (the “gold”)", p: ["Mix the sand with the metal nuts in the deep plate.", "Add some water and swirl the plate in circles, tilted over the basin.", "The light sand washes out and the heavy metal stays at the bottom: that's how miners separated gold!"] }, at: "Baroque art", m: "paper, a gold or yellow pencil, colored pencils", p: ["Draw the front of a church with two towers.", "Decorate it with lots of curves, spirals and flowers, really fancy like Baroque art.", "Color the details gold and glue it into the album."], q: "If you found a treasure, what would you do with it?" },
es: { h: "Nina encontró una piedrita brillante en el camino y gritó: “¡Oro!”. Era solo una piedrita con brillo de mica, pero el abuelo aprovechó la ocasión. “Hace unos trescientos años, mucha gente corrió a Minas Gerais por piedritas así”, contó. “Solo que allí eran de oro de verdad.”", t: "La fiebre del oro en Minas", f: "A fines del siglo XVII se descubrió mucho oro en Minas Gerais. Miles de personas fueron hacia allá y surgieron ciudades como Vila Rica, que hoy se llama Ouro Preto. Gran parte del oro fue llevada a Portugal.", x: "¡Ouro Preto fue el primer lugar de Brasil declarado Patrimonio Mundial por la UNESCO, en 1980!", s: ["Las iglesias de Minas tienen muchas decoraciones doradas, en un estilo llamado barroco.", "El artista más famoso de esa época fue el Aleijadinho, que esculpía en piedra jabón y madera.", "Aun con una enfermedad que afectó sus manos, el Aleijadinho siguió creando obras increíbles."], ex: { t: "Buscando oro en la palangana", m: "una palangana con agua, un plato hondo, arena, algunas tuercas o arandelas de metal (el “oro”)", p: ["Mezcla la arena con las tuerquitas de metal en el plato hondo.", "Agrega un poco de agua y mueve el plato en círculos, inclinado sobre la palangana.", "La arena liviana se va y el metal pesado queda en el fondo: ¡así separaban el oro los buscadores!"] }, at: "Arte barroco", m: "papel, lápiz dorado o amarillo, lápices de colores", p: ["Dibuja la fachada de una iglesia con dos torres.", "Adórnala con muchas curvas, espirales y flores, bien detallada como en el barroco.", "Pinta los detalles de dorado y pégala en el álbum."], q: "Si encontraras un tesoro, ¿qué harías con él?" } },

{ e: "📜", art: { b: "📜", s: ["🤫", "🕯️", "🔺", "🗝️"], c: ["#5A0B1B", "#B02C3A"] },
pt: { h: "Leo e Nina inventaram um código secreto para mandar bilhetinhos sem os adultos entenderem. O vovô achou graça e contou que, há mais de duzentos anos, um grupo em Minas Gerais também se reunia em segredo. “Eles sonhavam com um Brasil livre de Portugal”, disse.", t: "Tiradentes e a Inconfidência Mineira", f: "Em 1789, um grupo de pessoas em Minas Gerais planejou tornar a região independente de Portugal, porque os impostos sobre o ouro eram altíssimos. O plano foi descoberto antes de acontecer. Esse movimento ficou conhecido como Inconfidência Mineira.", x: "Tiradentes ganhou esse apelido porque também trabalhava como dentista, “tirando dentes”! O dia 21 de abril, feriado nacional, lembra sua história.", s: ["O nome verdadeiro de Tiradentes era Joaquim José da Silva Xavier.", "Os inconfidentes queriam uma bandeira com a frase em latim “Libertas quae sera tamen”, que quer dizer “Liberdade ainda que tardia”.", "Hoje essa frase está na bandeira do estado de Minas Gerais."], ex: { t: "Tinta invisível", m: "suco de limão, um cotonete, papel branco, um secador de cabelo (com um adulto)", p: ["Molhe o cotonete no suco de limão e escreva uma mensagem secreta no papel.", "Deixe secar: a mensagem some!", "Peça a um adulto para aquecer o papel com o secador: as letras aparecem marronzinhas. O calor “queima” o limão antes do papel."] }, at: "Minha bandeira", m: "papel, lápis de cor", p: ["Pense em uma ideia que você acha muito importante.", "Crie uma bandeira com cores, um símbolo e uma frase curta.", "Explique o significado para a família e cole no álbum."], q: "Que frase você colocaria numa bandeira sobre algo que acredita?" },
en: { h: "Leo and Nina invented a secret code to send notes the grown-ups couldn't understand. Grandpa found it funny and told them that more than two hundred years ago, a group in Minas Gerais also met in secret. “They dreamed of a Brazil free from Portugal,” he said.", t: "Tiradentes and the Minas Conspiracy", f: "In 1789, a group of people in Minas Gerais planned to make the region independent from Portugal, because the taxes on gold were extremely high. The plan was discovered before it could happen. This movement became known as the Inconfidência Mineira, or Minas Conspiracy.", x: "Tiradentes got that nickname because he also worked as a dentist, literally a “tooth-puller”! April 21, a national holiday in Brazil, remembers his story.", s: ["Tiradentes' real name was Joaquim José da Silva Xavier.", "The conspirators wanted a flag with the Latin phrase “Libertas quae sera tamen,” which means “Freedom, even if late.”", "Today that phrase is on the flag of the state of Minas Gerais."], ex: { t: "Invisible ink", m: "lemon juice, a cotton swab, white paper, a hair dryer (with a grown-up)", p: ["Dip the swab in lemon juice and write a secret message on the paper.", "Let it dry: the message disappears!", "Ask a grown-up to warm the paper with the hair dryer: the letters show up light brown. The heat “toasts” the lemon before the paper."] }, at: "My flag", m: "paper, colored pencils", p: ["Think of an idea you think is really important.", "Create a flag with colors, a symbol and a short motto.", "Explain what it means to your family and glue it into the album."], q: "What motto would you put on a flag about something you believe in?" },
es: { h: "Leo y Nina inventaron un código secreto para mandarse notitas sin que los adultos las entendieran. Al abuelo le dio gracia y les contó que, hace más de doscientos años, un grupo en Minas Gerais también se reunía en secreto. “Soñaban con un Brasil libre de Portugal”, dijo.", t: "Tiradentes y la Conjuración Minera", f: "En 1789, un grupo de personas en Minas Gerais planeó hacer independiente la región de Portugal, porque los impuestos sobre el oro eran altísimos. El plan fue descubierto antes de que ocurriera. Ese movimiento se conoce como la Inconfidência Mineira, o Conjuración Minera.", x: "¡Tiradentes recibió ese apodo porque también trabajaba de dentista, “sacando dientes”! El 21 de abril, feriado nacional en Brasil, recuerda su historia.", s: ["El nombre verdadero de Tiradentes era Joaquim José da Silva Xavier.", "Los conjurados querían una bandera con la frase en latín “Libertas quae sera tamen”, que quiere decir “Libertad aunque sea tardía”.", "Hoy esa frase está en la bandera del estado de Minas Gerais."], ex: { t: "Tinta invisible", m: "jugo de limón, un hisopo, papel blanco, un secador de pelo (con un adulto)", p: ["Moja el hisopo en el jugo de limón y escribe un mensaje secreto en el papel.", "Déjalo secar: ¡el mensaje desaparece!", "Pide a un adulto que caliente el papel con el secador: las letras aparecen marroncitas. El calor “tuesta” el limón antes que el papel."] }, at: "Mi bandera", m: "papel, lápices de colores", p: ["Piensa en una idea que te parezca muy importante.", "Crea una bandera con colores, un símbolo y un lema corto.", "Explica su significado a tu familia y pégala en el álbum."], q: "¿Qué lema pondrías en una bandera sobre algo en lo que crees?" } },

{ e: "👑", art: { b: "👑", s: ["⛵", "🌴", "📚", "🏛️"], c: ["#1B2A5A", "#3A5AB0"] },
pt: { h: "O vovô levou Nina e Leo para ver uma palmeira altíssima numa foto do Jardim Botânico do Rio. “Essa palmeira foi plantada por um rei”, contou. Leo arregalou os olhos: “Um rei de verdade morou no Brasil?”. “Morou, e trouxe a corte inteira junto”, respondeu o vovô.", t: "A família real chega ao Brasil", f: "Em 1808, o exército de Napoleão invadiu Portugal. A família real portuguesa, com milhares de pessoas, atravessou o oceano e veio morar no Rio de Janeiro. Foi a única vez na história que um rei europeu governou a partir de uma colônia.", x: "Logo depois de chegar, o príncipe Dom João criou o Jardim Botânico, o primeiro Banco do Brasil e a primeira gráfica oficial do país, tudo em 1808!", s: ["A família real trouxe uma biblioteca enorme, que deu origem à Biblioteca Nacional, uma das maiores do mundo.", "O Rio de Janeiro ganhou teatro, escolas e muitas novidades.", "Os portos do Brasil foram abertos para fazer comércio com outros países."], ex: { t: "Carimbo de batata", m: "meia batata (cortada por um adulto), um palito, tinta guache, papel", p: ["Peça a um adulto para cortar a batata ao meio e desenhar uma figura simples na parte lisa.", "O adulto tira a batata em volta do desenho com uma faquinha, deixando a figura em relevo.", "Passe tinta e carimbe várias vezes: você tem uma “gráfica” como a de 1808!"] }, at: "Jornal da corte", m: "papel, lápis", p: ["Faça a capa de um jornal de 1808 anunciando a chegada da família real.", "Invente uma manchete, desenhe os navios e escreva uma notícia curta.", "Use seu carimbo de batata para enfeitar e cole no álbum."], q: "Se um rei viesse morar na sua cidade, o que você mostraria a ele?" },
en: { h: "Grandpa showed Nina and Leo a photo of a very tall palm tree in Rio's Botanical Garden. “This palm was planted by a king,” he said. Leo's eyes went wide: “A real king lived in Brazil?” “He did, and he brought his whole court with him,” Grandpa answered.", t: "The royal family arrives in Brazil", f: "In 1808, Napoleon's army invaded Portugal. The Portuguese royal family, along with thousands of people, crossed the ocean and came to live in Rio de Janeiro. It was the only time in history a European monarch ruled from a colony.", x: "Soon after arriving, Prince Dom João created the Botanical Garden, the first Bank of Brazil and the country's first official printing press, all in 1808!", s: ["The royal family brought a huge library, which became the National Library, one of the largest in the world.", "Rio de Janeiro got a theater, schools and lots of new things.", "Brazil's ports were opened to trade with other countries."], ex: { t: "Potato stamp", m: "half a potato (cut by a grown-up), a toothpick, poster paint, paper", p: ["Ask a grown-up to cut the potato in half and draw a simple shape on the flat side.", "The grown-up carves away the potato around the shape with a small knife, leaving it raised.", "Paint it and stamp it again and again: you have a “printing press” like the one from 1808!"] }, at: "Royal court newspaper", m: "paper, pencil", p: ["Make the front page of an 1808 newspaper announcing the royal family's arrival.", "Invent a headline, draw the ships and write a short news story.", "Decorate it with your potato stamp and glue it into the album."], q: "If a king came to live in your town, what would you show him?" },
es: { h: "El abuelo les mostró a Nina y Leo la foto de una palmera altísima en el Jardín Botánico de Río. “Esta palmera la plantó un rey”, contó. Leo abrió grandes los ojos: “¿Un rey de verdad vivió en Brasil?”. “Sí, y trajo a toda la corte con él”, respondió el abuelo.", t: "La familia real llega a Brasil", f: "En 1808, el ejército de Napoleón invadió Portugal. La familia real portuguesa, con miles de personas, cruzó el océano y vino a vivir a Río de Janeiro. Fue la única vez en la historia que un monarca europeo gobernó desde una colonia.", x: "¡Poco después de llegar, el príncipe Don Juan creó el Jardín Botánico, el primer Banco de Brasil y la primera imprenta oficial del país, todo en 1808!", s: ["La familia real trajo una biblioteca enorme, que dio origen a la Biblioteca Nacional, una de las más grandes del mundo.", "Río de Janeiro ganó teatro, escuelas y muchas novedades.", "Los puertos de Brasil se abrieron para comerciar con otros países."], ex: { t: "Sello de papa", m: "media papa (cortada por un adulto), un palillo, témpera, papel", p: ["Pide a un adulto que corte la papa por la mitad y dibuje una figura simple en la parte lisa.", "El adulto quita la papa alrededor del dibujo con un cuchillito, dejando la figura en relieve.", "Pásale pintura y sella varias veces: ¡tienes una “imprenta” como la de 1808!"] }, at: "Periódico de la corte", m: "papel, lápiz", p: ["Haz la portada de un periódico de 1808 anunciando la llegada de la familia real.", "Inventa un titular, dibuja los barcos y escribe una noticia corta.", "Decóralo con tu sello de papa y pégalo en el álbum."], q: "Si un rey viniera a vivir a tu ciudad, ¿qué le mostrarías?" } },

{ e: "🗡️", art: { b: "🐎", s: ["📣", "🌿", "📜", "🎉"], c: ["#0B4F2C", "#D4B02C"] },
pt: { h: "Nina viu um quadro enorme com um homem a cavalo levantando a espada na beira de um riacho. “É o Grito do Ipiranga”, explicou o vovô. “Mas tem uma pessoa importante que não aparece no quadro.” Nina e Leo quiseram saber quem era, e o vovô contou sobre uma princesa que amava ciência.", t: "A Independência do Brasil", f: "Em 7 de setembro de 1822, às margens do riacho Ipiranga, em São Paulo, Dom Pedro declarou o Brasil independente de Portugal. Logo depois, ele se tornou o primeiro imperador do Brasil, Dom Pedro I.", x: "Dias antes do grito, a princesa Leopoldina, que governava enquanto Dom Pedro viajava, reuniu os conselheiros e mandou uma carta pedindo que ele declarasse a independência!", s: ["Leopoldina era austríaca e adorava ciências naturais: colecionava plantas, minerais e animais.", "Ela trouxe cientistas da Europa que estudaram a natureza brasileira por anos.", "O dia 7 de setembro é feriado nacional, o Dia da Independência."], ex: { t: "Herbário da Leopoldina", m: "folhas e flores do chão, papel-toalha, livros pesados, papel e cola", p: ["Recolha folhas e flores caídas, de formatos diferentes.", "Coloque cada uma entre duas folhas de papel-toalha, dentro de um livro, e ponha livros pesados por cima.", "Depois de uma semana, elas estarão secas e retinhas. Cole num papel e escreva onde achou cada uma."] }, at: "O quadro que faltava", m: "papel, lápis de cor", p: ["Desenhe a cena da independência do seu jeito.", "Inclua a princesa Leopoldina com a carta e alguns de seus cientistas.", "Dê um título ao seu quadro e cole no álbum."], q: "Por que será que algumas pessoas importantes ficam de fora dos livros e dos quadros?" },
en: { h: "Nina saw a huge painting of a man on horseback raising his sword beside a stream. “That's the Cry of Ipiranga,” Grandpa explained. “But there's an important person who doesn't appear in the painting.” Nina and Leo wanted to know who, and Grandpa told them about a princess who loved science.", t: "Brazil's Independence", f: "On September 7, 1822, on the banks of the Ipiranga stream in São Paulo, Dom Pedro declared Brazil independent from Portugal. Soon after, he became Brazil's first emperor, Dom Pedro I.", x: "Days before the famous cry, Princess Leopoldina, who was in charge while Dom Pedro traveled, gathered the advisors and sent him a letter urging him to declare independence!", s: ["Leopoldina was Austrian and loved natural science: she collected plants, minerals and animals.", "She brought scientists from Europe who studied Brazil's nature for years.", "September 7 is a national holiday in Brazil, Independence Day."], ex: { t: "Leopoldina's herbarium", m: "fallen leaves and flowers, paper towels, heavy books, paper and glue", p: ["Collect fallen leaves and flowers of different shapes.", "Place each one between two paper towels inside a book, and stack heavy books on top.", "After a week, they'll be dry and flat. Glue them onto paper and write where you found each one."] }, at: "The missing painting", m: "paper, colored pencils", p: ["Draw the independence scene your own way.", "Include Princess Leopoldina with her letter and some of her scientists.", "Give your painting a title and glue it into the album."], q: "Why do you think some important people get left out of books and paintings?" },
es: { h: "Nina vio un cuadro enorme con un hombre a caballo levantando la espada junto a un arroyo. “Es el Grito de Ipiranga”, explicó el abuelo. “Pero hay una persona importante que no aparece en el cuadro.” Nina y Leo quisieron saber quién era, y el abuelo les habló de una princesa que amaba la ciencia.", t: "La Independencia de Brasil", f: "El 7 de septiembre de 1822, a orillas del arroyo Ipiranga, en São Paulo, Don Pedro declaró a Brasil independiente de Portugal. Poco después se convirtió en el primer emperador de Brasil, Don Pedro I.", x: "¡Días antes del grito, la princesa Leopoldina, que gobernaba mientras Don Pedro viajaba, reunió a los consejeros y le mandó una carta pidiéndole que declarara la independencia!", s: ["Leopoldina era austríaca y adoraba las ciencias naturales: coleccionaba plantas, minerales y animales.", "Trajo científicos de Europa que estudiaron la naturaleza brasileña durante años.", "El 7 de septiembre es feriado nacional en Brasil, el Día de la Independencia."], ex: { t: "Herbario de Leopoldina", m: "hojas y flores del suelo, papel de cocina, libros pesados, papel y pegamento", p: ["Junta hojas y flores caídas de formas diferentes.", "Pon cada una entre dos hojas de papel de cocina, dentro de un libro, y coloca libros pesados encima.", "Después de una semana estarán secas y planas. Pégalas en un papel y escribe dónde encontraste cada una."] }, at: "El cuadro que faltaba", m: "papel, lápices de colores", p: ["Dibuja la escena de la independencia a tu manera.", "Incluye a la princesa Leopoldina con su carta y a algunos de sus científicos.", "Ponle un título a tu cuadro y pégalo en el álbum."], q: "¿Por qué crees que algunas personas importantes quedan fuera de los libros y los cuadros?" } },

{ e: "📷", art: { b: "📷", s: ["👑", "🔭", "☎️", "📚"], c: ["#2A1B4E", "#6A4AA0"] },
pt: { h: "Leo achou uma foto antiga, em preto e branco, de um homem de barba branca comprida. “Quem é esse vovô?”, perguntou. O vovô riu: “Não é meu parente! É Dom Pedro II, que virou imperador quando tinha só 5 anos.” Leo tentou imaginar como seria mandar num país inteiro com 5 anos.", t: "O imperador que amava ciência", f: "Dom Pedro II se tornou imperador aos 5 anos, quando o pai voltou para Portugal. Enquanto ele crescia, outras pessoas governavam. Aos 14 anos, ele assumiu o trono e governou o Brasil por quase 50 anos.", x: "Dom Pedro II foi um dos primeiros fotógrafos do Brasil! Ele também conheceu o inventor do telefone, Graham Bell, e foi uma das primeiras pessoas a testar o aparelho, em 1876.", s: ["Ele adorava estudar línguas, astronomia e ciências, e trocava cartas com cientistas do mundo inteiro.", "Durante o seu governo, o Brasil ganhou ferrovias, telégrafo e cabos submarinos ligando o país à Europa.", "Dom Pedro II deixou uma coleção enorme de fotografias, que hoje é guardada pela Biblioteca Nacional."], ex: { t: "Câmera escura de caixa", m: "uma caixa de sapato, papel-manteiga, fita adesiva, um prego ou lápis (com um adulto)", p: ["Um adulto faz um furinho pequeno no meio de um dos lados menores da caixa.", "Corte uma janela no lado oposto e cubra com papel-manteiga. Feche a tampa.", "Aponte o furinho para uma janela clara e olhe o papel: a imagem aparece de cabeça para baixo! As primeiras câmeras funcionavam assim."] }, at: "Retrato antigo", m: "papel, lápis grafite", p: ["Peça para alguém da família posar bem paradinho, como nas fotos antigas.", "Desenhe o retrato só em preto, cinza e branco.", "Faça uma moldura e cole no álbum, com a data de hoje."], q: "Se você fosse imperador ou imperatriz por um dia, o que mudaria?" },
en: { h: "Leo found an old black-and-white photo of a man with a long white beard. “Who's that grandpa?” he asked. Grandpa laughed: “He's not my relative! That's Dom Pedro II, who became emperor when he was only 5.” Leo tried to imagine running a whole country at age 5.", t: "The emperor who loved science", f: "Dom Pedro II became emperor at age 5, when his father returned to Portugal. While he was growing up, other people ruled for him. At 14, he took the throne and governed Brazil for almost 50 years.", x: "Dom Pedro II was one of the first photographers in Brazil! He also met the inventor of the telephone, Alexander Graham Bell, and was one of the first people to try the device, in 1876.", s: ["He loved studying languages, astronomy and science, and exchanged letters with scientists all over the world.", "During his reign, Brazil got railways, the telegraph and undersea cables linking the country to Europe.", "Dom Pedro II left a huge collection of photographs, now kept by Brazil's National Library."], ex: { t: "Shoebox camera obscura", m: "a shoebox, wax paper, tape, a nail or pencil (with a grown-up)", p: ["A grown-up pokes a small hole in the middle of one of the short sides of the box.", "Cut a window on the opposite side and cover it with wax paper. Close the lid.", "Point the hole at a bright window and look at the paper: the image appears upside down! The first cameras worked like this."] }, at: "Old-time portrait", m: "paper, graphite pencil", p: ["Ask someone in your family to pose very still, like in old photos.", "Draw the portrait using only black, gray and white.", "Make a frame and glue it into the album with today's date."], q: "If you were emperor or empress for a day, what would you change?" },
es: { h: "Leo encontró una foto antigua, en blanco y negro, de un hombre con una larga barba blanca. “¿Quién es ese abuelito?”, preguntó. El abuelo se rió: “¡No es mi pariente! Es Don Pedro II, que se convirtió en emperador cuando tenía solo 5 años.” Leo trató de imaginar cómo sería gobernar un país entero con 5 años.", t: "El emperador que amaba la ciencia", f: "Don Pedro II se convirtió en emperador a los 5 años, cuando su padre volvió a Portugal. Mientras crecía, otras personas gobernaban por él. A los 14 años asumió el trono y gobernó Brasil durante casi 50 años.", x: "¡Don Pedro II fue uno de los primeros fotógrafos de Brasil! También conoció al inventor del teléfono, Graham Bell, y fue una de las primeras personas en probar el aparato, en 1876.", s: ["Le encantaba estudiar idiomas, astronomía y ciencias, y se escribía con científicos de todo el mundo.", "Durante su gobierno, Brasil tuvo ferrocarriles, telégrafo y cables submarinos que unían el país con Europa.", "Don Pedro II dejó una enorme colección de fotografías, que hoy guarda la Biblioteca Nacional de Brasil."], ex: { t: "Cámara oscura de caja", m: "una caja de zapatos, papel manteca, cinta adhesiva, un clavo o lápiz (con un adulto)", p: ["Un adulto hace un agujerito en el medio de uno de los lados cortos de la caja.", "Corta una ventana en el lado opuesto y cúbrela con papel manteca. Cierra la tapa.", "Apunta el agujerito hacia una ventana clara y mira el papel: ¡la imagen aparece al revés! Las primeras cámaras funcionaban así."] }, at: "Retrato antiguo", m: "papel, lápiz negro", p: ["Pide a alguien de tu familia que pose bien quieto, como en las fotos antiguas.", "Dibuja el retrato solo en negro, gris y blanco.", "Hazle un marco y pégalo en el álbum con la fecha de hoy."], q: "Si fueras emperador o emperatriz por un día, ¿qué cambiarías?" } },

{ e: "🕊️", art: { b: "🕊️", s: ["📜", "✊", "⛓️", "🌅"], c: ["#0B3A4E", "#2C8AB0"] },
pt: { h: "Nina leu num livro que a escravidão no Brasil tinha acabado em 1888. “Só isso? Foi só uma princesa assinar um papel?”, perguntou. O vovô balançou a cabeça: “O papel foi importante, mas antes dele teve muita gente lutando por anos. Deixa eu contar sobre eles.”", t: "O fim da escravidão", f: "Em 13 de maio de 1888, a princesa Isabel assinou a Lei Áurea, que acabou com a escravidão no Brasil. Essa conquista veio depois de muita luta de pessoas negras, abolicionistas, jornalistas, advogados e até jangadeiros.", x: "O Brasil foi o último país das Américas a acabar com a escravidão. E o Ceará libertou as pessoas escravizadas quatro anos antes, em 1884!", s: ["Luiz Gama foi escravizado quando criança, conquistou a liberdade, virou advogado e ajudou a libertar centenas de pessoas na Justiça.", "No Ceará, o jangadeiro Francisco José do Nascimento, o Dragão do Mar, liderou a recusa de transportar pessoas escravizadas.", "Depois da Lei Áurea, as pessoas libertadas não receberam terras nem ajuda, e as desigualdades que isso criou ainda precisam ser enfrentadas hoje."], ex: { t: "A força da união", m: "palitos de picolé ou de churrasco sem ponta (com um adulto), elástico", p: ["Tente quebrar um palito sozinho: é fácil.", "Agora junte 10 palitos com um elástico e tente quebrar o feixe.", "Muito mais difícil! Juntas, as pessoas que lutaram contra a escravidão ficaram mais fortes."] }, at: "Carta para Luiz Gama", m: "papel, lápis", p: ["Escreva uma cartinha para Luiz Gama contando o que você aprendeu sobre ele.", "Diga o que você faria hoje para ajudar a tornar o mundo mais justo.", "Desenhe uma pomba da paz e cole no álbum."], q: "O que você pode fazer quando vê alguém sendo tratado de forma injusta?" },
en: { h: "Nina read in a book that slavery in Brazil ended in 1888. “That's it? A princess just signed a piece of paper?” she asked. Grandpa shook his head: “The paper mattered, but before it there were many people fighting for years. Let me tell you about them.”", t: "The end of slavery", f: "On May 13, 1888, Princess Isabel signed the Golden Law, which ended slavery in Brazil. This victory came after a long struggle by Black people, abolitionists, journalists, lawyers and even raft fishermen.", x: "Brazil was the last country in the Americas to end slavery. And the province of Ceará freed its enslaved people four years earlier, in 1884!", s: ["Luiz Gama was enslaved as a child, won his freedom, became a lawyer and helped free hundreds of people in court.", "In Ceará, the raft fisherman Francisco José do Nascimento, called the Sea Dragon, led a refusal to carry enslaved people on the boats.", "After the Golden Law, freed people received no land or help, and the inequalities this created still need to be tackled today."], ex: { t: "Strength in unity", m: "popsicle sticks or blunt skewers (with a grown-up), a rubber band", p: ["Try to break one stick by yourself: it's easy.", "Now bundle 10 sticks with a rubber band and try to break the bundle.", "Much harder! Together, the people who fought slavery became stronger."] }, at: "A letter to Luiz Gama", m: "paper, pencil", p: ["Write a short letter to Luiz Gama telling him what you learned about him.", "Say what you would do today to help make the world fairer.", "Draw a peace dove and glue it into the album."], q: "What can you do when you see someone being treated unfairly?" },
es: { h: "Nina leyó en un libro que la esclavitud en Brasil terminó en 1888. “¿Eso es todo? ¿Solo una princesa firmó un papel?”, preguntó. El abuelo negó con la cabeza: “El papel fue importante, pero antes hubo mucha gente luchando durante años. Déjenme contarles sobre ellos.”", t: "El fin de la esclavitud", f: "El 13 de mayo de 1888, la princesa Isabel firmó la Ley Áurea, que terminó con la esclavitud en Brasil. Esa conquista llegó después de mucha lucha de personas negras, abolicionistas, periodistas, abogados y hasta pescadores en balsa.", x: "Brasil fue el último país de América en terminar con la esclavitud. ¡Y la provincia de Ceará liberó a las personas esclavizadas cuatro años antes, en 1884!", s: ["Luiz Gama fue esclavizado de niño, conquistó su libertad, se hizo abogado y ayudó a liberar a cientos de personas en la Justicia.", "En Ceará, el balsero Francisco José do Nascimento, llamado el Dragón del Mar, lideró la negativa a transportar personas esclavizadas.", "Después de la Ley Áurea, las personas liberadas no recibieron tierras ni ayuda, y las desigualdades que eso creó todavía hay que enfrentarlas hoy."], ex: { t: "La fuerza de la unión", m: "palitos de helado o de brochette sin punta (con un adulto), una gomita elástica", p: ["Intenta romper un palito solo: es fácil.", "Ahora junta 10 palitos con una gomita e intenta romper el atado.", "¡Mucho más difícil! Juntas, las personas que lucharon contra la esclavitud se hicieron más fuertes."] }, at: "Carta a Luiz Gama", m: "papel, lápiz", p: ["Escríbele una cartita a Luiz Gama contándole lo que aprendiste sobre él.", "Dile qué harías hoy para ayudar a que el mundo sea más justo.", "Dibuja una paloma de la paz y pégala en el álbum."], q: "¿Qué puedes hacer cuando ves que alguien es tratado de forma injusta?" } },

{ e: "⭐", art: { b: "⭐", s: ["🌌", "🏛️", "✨", "🌟"], c: ["#0B1B4E", "#2C4AB0"] },
pt: { h: "Leo estava desenhando a bandeira do Brasil e perguntou por que tinha tantas estrelinhas no círculo azul. O vovô apagou a luz e acendeu uma lanterna atrás de um papel furado, que fez estrelas no teto. “Essas estrelas são o céu do Rio numa manhã muito especial”, disse.", t: "O Brasil vira República", f: "Em 15 de novembro de 1889, o marechal Deodoro da Fonseca proclamou a República, e o Brasil deixou de ter imperador. A partir daí, o país passou a ter presidentes. Dom Pedro II e sua família foram viver na Europa.", x: "As estrelas da bandeira mostram o céu do Rio de Janeiro na manhã de 15 de novembro de 1889! Hoje são 27 estrelas: uma para cada estado e uma para o Distrito Federal.", s: ["A bandeira com o lema “Ordem e Progresso” foi adotada quatro dias depois da proclamação.", "O primeiro presidente do Brasil foi o próprio Deodoro da Fonseca.", "O dia 15 de novembro é feriado nacional, o Dia da Proclamação da República."], ex: { t: "Céu de lanterna", m: "um pedaço de cartolina preta, um lápis com ponta (com um adulto), uma lanterna, um quarto escuro", p: ["Desenhe pontinhos na cartolina imitando o Cruzeiro do Sul, que aparece na bandeira.", "Com um adulto, fure cada ponto com a ponta do lápis.", "No quarto escuro, acenda a lanterna atrás da cartolina: as estrelas aparecem no teto!"] }, at: "Minha estrela na bandeira", m: "papel, lápis de cor, uma imagem da bandeira", p: ["Desenhe a bandeira do Brasil com o círculo azul e as estrelas.", "Com um adulto, descubra qual estrela representa o seu estado.", "Pinte essa estrela de outra cor e cole no álbum."], q: "Como você acha que um presidente deve ser escolhido?" },
en: { h: "Leo was drawing Brazil's flag and asked why there were so many little stars in the blue circle. Grandpa turned off the light and shone a flashlight behind a paper full of holes, making stars on the ceiling. “These stars are the sky over Rio on a very special morning,” he said.", t: "Brazil becomes a Republic", f: "On November 15, 1889, Marshal Deodoro da Fonseca proclaimed the Republic, and Brazil no longer had an emperor. From then on, the country had presidents. Dom Pedro II and his family went to live in Europe.", x: "The stars on the flag show the sky over Rio de Janeiro on the morning of November 15, 1889! Today there are 27 stars: one for each state and one for the Federal District.", s: ["The flag with the motto “Ordem e Progresso” (Order and Progress) was adopted four days after the proclamation.", "Brazil's first president was Deodoro da Fonseca himself.", "November 15 is a national holiday in Brazil, Proclamation of the Republic Day."], ex: { t: "Flashlight sky", m: "a piece of black poster board, a sharp pencil (with a grown-up), a flashlight, a dark room", p: ["Draw dots on the poster board to copy the Southern Cross, which appears on the flag.", "With a grown-up, poke each dot with the pencil tip.", "In the dark room, shine the flashlight behind the board: stars appear on the ceiling!"] }, at: "My star on the flag", m: "paper, colored pencils, a picture of the flag", p: ["Draw Brazil's flag with the blue circle and the stars.", "With a grown-up, find out which star stands for your state (or pick one if you live elsewhere).", "Color that star a different color and glue it into the album."], q: "How do you think a president should be chosen?" },
es: { h: "Leo estaba dibujando la bandera de Brasil y preguntó por qué había tantas estrellitas en el círculo azul. El abuelo apagó la luz y encendió una linterna detrás de un papel agujereado, que hizo estrellas en el techo. “Estas estrellas son el cielo de Río en una mañana muy especial”, dijo.", t: "Brasil se vuelve República", f: "El 15 de noviembre de 1889, el mariscal Deodoro da Fonseca proclamó la República, y Brasil dejó de tener emperador. A partir de entonces, el país tuvo presidentes. Don Pedro II y su familia se fueron a vivir a Europa.", x: "¡Las estrellas de la bandera muestran el cielo de Río de Janeiro en la mañana del 15 de noviembre de 1889! Hoy son 27 estrellas: una por cada estado y una por el Distrito Federal.", s: ["La bandera con el lema “Ordem e Progresso” (Orden y Progreso) se adoptó cuatro días después de la proclamación.", "El primer presidente de Brasil fue el propio Deodoro da Fonseca.", "El 15 de noviembre es feriado nacional en Brasil, el Día de la Proclamación de la República."], ex: { t: "Cielo de linterna", m: "un pedazo de cartulina negra, un lápiz con punta (con un adulto), una linterna, un cuarto oscuro", p: ["Dibuja puntitos en la cartulina imitando la Cruz del Sur, que aparece en la bandera.", "Con un adulto, perfora cada punto con la punta del lápiz.", "En el cuarto oscuro, enciende la linterna detrás de la cartulina: ¡las estrellas aparecen en el techo!"] }, at: "Mi estrella en la bandera", m: "papel, lápices de colores, una imagen de la bandera", p: ["Dibuja la bandera de Brasil con el círculo azul y las estrellas.", "Con un adulto, descubre qué estrella representa a cada estado y elige tu favorita.", "Pinta esa estrella de otro color y pégala en el álbum."], q: "¿Cómo crees que se debería elegir a un presidente?" } },

{ e: "🧳", art: { b: "🧳", s: ["🚢", "🍕", "🍣", "🥙"], c: ["#4E1B3A", "#B03A7A"] },
pt: { h: "No almoço de domingo, a mesa tinha macarrão, esfiha e até sushi que uma tia trouxe. “Parece um almoço do mundo inteiro!”, disse Leo. O vovô sorriu: “E é! Muitas famílias vieram de longe para o Brasil e trouxeram suas receitas na mala.”", t: "Gente de todo canto", f: "A partir do fim dos anos 1800, milhões de imigrantes chegaram ao Brasil. Vieram italianos, portugueses, espanhóis, alemães, japoneses, sírios, libaneses e muitos outros. Eles trabalharam no campo, abriram comércios e ajudaram a construir cidades.", x: "O Brasil tem a maior comunidade de descendentes de japoneses fora do Japão! Os primeiros chegaram no navio Kasato Maru, em 1908.", s: ["Muitos imigrantes italianos foram trabalhar nas fazendas de café de São Paulo.", "No Sul, imigrantes alemães e italianos fundaram cidades com casas e festas típicas de suas terras.", "Ainda hoje chegam ao Brasil pessoas de muitos países, como Haiti, Venezuela, Bolívia e Angola."], ex: { t: "Balão que enche sozinho", m: "uma garrafinha, uma colher de fermento biológico seco, uma colher de açúcar, água morna, uma bexiga", p: ["Coloque água morna na garrafa até um terço, com o açúcar e o fermento, e mexa.", "Encaixe a bexiga vazia na boca da garrafa.", "Espere uns 20 minutos: a bexiga enche! O fermento solta gás, o mesmo que faz o pão crescer nas padarias que os imigrantes abriram."] }, at: "Mala da minha família", m: "papel, lápis de cor", p: ["Desenhe uma mala grande e aberta.", "Pergunte aos adultos de onde vieram os avós e bisavós da família.", "Desenhe dentro da mala uma comida, uma palavra ou um costume que veio com eles e cole no álbum."], q: "Se você fosse morar em outro país, o que levaria na mala?" },
en: { h: "At Sunday lunch, the table had pasta, Middle Eastern esfiha and even sushi an aunt brought. “It's like a lunch from the whole world!” said Leo. Grandpa smiled: “It is! Many families came to Brazil from far away and brought their recipes in their suitcases.”", t: "People from everywhere", f: "Starting in the late 1800s, millions of immigrants arrived in Brazil. Italians, Portuguese, Spanish, Germans, Japanese, Syrians, Lebanese and many others came. They worked on farms, opened shops and helped build cities.", x: "Brazil has the largest community of Japanese descent outside Japan! The first group arrived on the ship Kasato Maru in 1908.", s: ["Many Italian immigrants went to work on São Paulo's coffee farms.", "In the South, German and Italian immigrants founded towns with houses and festivals from their homelands.", "People still come to Brazil today from many countries, like Haiti, Venezuela, Bolivia and Angola."], ex: { t: "The self-inflating balloon", m: "a small bottle, a spoonful of dry yeast, a spoonful of sugar, warm water, a balloon", p: ["Fill the bottle one-third with warm water, add the sugar and yeast, and swirl.", "Stretch the empty balloon over the mouth of the bottle.", "Wait about 20 minutes: the balloon inflates! The yeast gives off gas, the same gas that makes bread rise in the bakeries immigrants opened."] }, at: "My family's suitcase", m: "paper, colored pencils", p: ["Draw a big open suitcase.", "Ask the grown-ups where the family's grandparents and great-grandparents came from.", "Inside the suitcase, draw a food, a word or a custom that came with them, and glue it into the album."], q: "If you moved to another country, what would you pack in your suitcase?" },
es: { h: "En el almuerzo del domingo, la mesa tenía fideos, esfihas y hasta sushi que trajo una tía. “¡Parece un almuerzo del mundo entero!”, dijo Leo. El abuelo sonrió: “¡Y lo es! Muchas familias vinieron de lejos a Brasil y trajeron sus recetas en la maleta.”", t: "Gente de todas partes", f: "Desde fines del siglo XIX, millones de inmigrantes llegaron a Brasil. Vinieron italianos, portugueses, españoles, alemanes, japoneses, sirios, libaneses y muchos otros. Trabajaron en el campo, abrieron comercios y ayudaron a construir ciudades.", x: "¡Brasil tiene la mayor comunidad de descendientes de japoneses fuera de Japón! Los primeros llegaron en el barco Kasato Maru, en 1908.", s: ["Muchos inmigrantes italianos fueron a trabajar en las haciendas de café de São Paulo.", "En el Sur, inmigrantes alemanes e italianos fundaron ciudades con casas y fiestas típicas de sus tierras.", "Todavía hoy llegan a Brasil personas de muchos países, como Haití, Venezuela, Bolivia y Angola."], ex: { t: "El globo que se infla solo", m: "una botellita, una cucharada de levadura seca, una cucharada de azúcar, agua tibia, un globo", p: ["Llena un tercio de la botella con agua tibia, agrega el azúcar y la levadura, y agita suavemente.", "Coloca el globo vacío en la boca de la botella.", "Espera unos 20 minutos: ¡el globo se infla! La levadura suelta gas, el mismo que hace crecer el pan en las panaderías que abrieron los inmigrantes."] }, at: "La maleta de mi familia", m: "papel, lápices de colores", p: ["Dibuja una maleta grande y abierta.", "Pregunta a los adultos de dónde vinieron los abuelos y bisabuelos de la familia.", "Dibuja dentro de la maleta una comida, una palabra o una costumbre que llegó con ellos y pégala en el álbum."], q: "Si te mudaras a otro país, ¿qué llevarías en la maleta?" } },

{ e: "☕", art: { b: "☕", s: ["🚂", "🌱", "🛤️", "💨"], c: ["#3A1B0B", "#8A4A2C"] },
pt: { h: "O vovô passou um cafezinho, e o cheiro tomou a casa toda. Nina perguntou por que os adultos gostam tanto de café. “Não sei explicar”, riu o vovô, “mas sei que o café já foi o produto mais importante do Brasil. Por causa dele, o país ganhou trens!”", t: "Café com trem", f: "No século 19, o Brasil se tornou o maior produtor de café do mundo, e é até hoje. Para levar o café das fazendas até os portos, foram construídas ferrovias, e os trens a vapor começaram a cruzar o país.", x: "O café não é daqui: ele veio da Etiópia, na África, e chegou ao Brasil por volta de 1727, no Pará!", s: ["A primeira ferrovia do Brasil foi inaugurada em 1854, no Rio de Janeiro, por iniciativa do Barão de Mauá.", "Os trens a vapor queimavam lenha ou carvão para ferver água e o vapor movia as rodas.", "Muitas cidades do interior nasceram em volta das estações de trem."], ex: { t: "Arco-íris no filtro", m: "um filtro de café de papel, canetinhas coloridas (não permanentes), um copo com um pouquinho de água", p: ["Corte uma tira do filtro e faça um ponto grosso de canetinha preta ou marrom perto da ponta.", "Coloque a tira no copo, com a ponta na água, sem molhar o ponto.", "Espere: a água sobe pelo papel e separa a tinta em várias cores escondidas!"] }, at: "Trem do café", m: "caixinhas de fósforo ou de remédio vazias, tampinhas, cola, barbante", p: ["Faça vagões com as caixinhas e rodas com as tampinhas.", "Ligue os vagões com barbante e enfeite a locomotiva com uma chaminé.", "Desenhe o seu trem no álbum, carregado de café."], q: "Se você pudesse viajar de trem, para onde iria?" },
en: { h: "Grandpa brewed some coffee, and the smell filled the whole house. Nina asked why grown-ups like coffee so much. “I can't explain it,” Grandpa laughed, “but I know coffee was once Brazil's most important product. Because of it, the country got trains!”", t: "Coffee and trains", f: "In the 1800s, Brazil became the world's biggest coffee producer, and it still is today. To carry coffee from the farms to the ports, railways were built, and steam trains began crossing the country.", x: "Coffee isn't originally from Brazil: it came from Ethiopia, in Africa, and reached Brazil around 1727, in the state of Pará!", s: ["Brazil's first railway opened in 1854, in Rio de Janeiro, led by the Baron of Mauá.", "Steam trains burned wood or coal to boil water, and the steam turned the wheels.", "Many inland towns grew up around train stations."], ex: { t: "Rainbow in a filter", m: "a paper coffee filter, washable colored markers, a glass with a little water", p: ["Cut a strip from the filter and make a thick dot of black or brown marker near the end.", "Place the strip in the glass with the end in the water, without wetting the dot.", "Wait: the water climbs the paper and splits the ink into several hidden colors!"] }, at: "Coffee train", m: "empty matchboxes or small boxes, bottle caps, glue, string", p: ["Make train cars from the boxes and wheels from the caps.", "Connect the cars with string and give the engine a smokestack.", "Draw your train in the album, loaded with coffee."], q: "If you could travel by train, where would you go?" },
es: { h: "El abuelo preparó un cafecito, y el olor llenó toda la casa. Nina preguntó por qué a los adultos les gusta tanto el café. “No sé explicarlo”, se rió el abuelo, “pero sé que el café fue el producto más importante de Brasil. ¡Gracias a él, el país tuvo trenes!”", t: "Café con tren", f: "En el siglo XIX, Brasil se convirtió en el mayor productor de café del mundo, y lo es hasta hoy. Para llevar el café de las haciendas a los puertos se construyeron ferrocarriles, y los trenes a vapor empezaron a cruzar el país.", x: "¡El café no es de aquí: vino de Etiopía, en África, y llegó a Brasil alrededor de 1727, en Pará!", s: ["El primer ferrocarril de Brasil se inauguró en 1854, en Río de Janeiro, por iniciativa del Barón de Mauá.", "Los trenes a vapor quemaban leña o carbón para hervir agua, y el vapor movía las ruedas.", "Muchas ciudades del interior nacieron alrededor de las estaciones de tren."], ex: { t: "Arcoíris en el filtro", m: "un filtro de café de papel, marcadores de colores lavables, un vaso con un poquito de agua", p: ["Corta una tira del filtro y haz un punto grueso de marcador negro o marrón cerca de la punta.", "Pon la tira en el vaso con la punta en el agua, sin mojar el punto.", "Espera: ¡el agua sube por el papel y separa la tinta en varios colores escondidos!"] }, at: "Tren del café", m: "cajitas de fósforos o de remedios vacías, tapitas, pegamento, cordel", p: ["Haz vagones con las cajitas y ruedas con las tapitas.", "Une los vagones con cordel y ponle una chimenea a la locomotora.", "Dibuja tu tren en el álbum, cargado de café."], q: "Si pudieras viajar en tren, ¿adónde irías?" } },
];
